<script setup>
import { useDialogEscape } from '../../lib/dialog.js';
import { computed,ref } from 'vue';import { Head,Link,router,useForm } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';import Errors from '../../Components/Errors.vue';
const props=defineProps({collection:Object,shared:{type:Boolean,default:false},availableWords:{type:Array,default:()=>[]}});
const showAdd=ref(false),showEdit=ref(false),query=ref(''),copyStatus=ref('');
const add=useForm({word_ids:[]});const edit=useForm({title:props.collection.title,description:props.collection.description??''});
const base=computed(()=>props.shared?`/s/${props.collection.share_uuid}`:`/collections/${props.collection.id}`);
const candidates=computed(()=>props.availableWords.filter(w=>!props.collection.words.some(x=>x.id===w.id)&&`${w.term} ${w.definition}`.toLowerCase().includes(query.value.toLowerCase())));
const shareUrl=computed(()=>typeof window==='undefined'?'':`${window.location.origin}/s/${props.collection.share_uuid}`);
async function copy(){try{await navigator.clipboard.writeText(shareUrl.value);copyStatus.value='Link copied';}catch{copyStatus.value='Select and copy the link below.';}}
function disable(){if(confirm('Turn sharing off? Anyone using this link will lose access. A new link is created if you share again.'))router.delete(`${base.value}/sharing`);}
function remove(word){if(confirm(`Remove “${word.term}” from this collection? It stays in your word pool.`))router.delete(`${base.value}/words/${word.id}`);}
function destroy(){if(confirm('Delete this collection? Your words will stay in your pool.'))router.delete(base.value);}
useDialogEscape(()=>{showAdd.value=false;showEdit.value=false;});
</script>
<template><Head :title="collection.title"/><AppLayout :title="collection.title" :subtitle="collection.description" :shared="shared"><template #actions><button v-if="!shared" class="button secondary" @click="showEdit=true">Edit collection</button><span v-else class="pill dark">OPEN TO EVERYONE WITH THIS LINK</span></template><div class="mode-grid"><Link v-for="item in [{mode:'flashcards',icon:'▱',name:'Flashcards',text:'Flip. Recall. Repeat.'},{mode:'study',icon:'✦',name:'Study',text:'Practice at your own pace.'},{mode:'test',icon:'✓',name:'Test',text:'Find out what sticks.'}]" :key="item.mode" :href="`${base}/study?mode=${item.mode}`" class="mode-card"><span>{{item.icon}}</span><h3>{{item.name}}</h3><p>{{item.text}}</p><b>Start →</b></Link></div><section v-if="!shared" class="sharing panel"><div><span class="eyebrow">KNOWLEDGE IS BETTER SHARED</span><h3>{{collection.share_uuid?'Your link is ready.':'Keep it private. Or pass it on.'}}</h3><p class="muted">{{collection.share_uuid?'Anyone with this link can study without signing in. Your private notes stay private.':'Turn on link sharing whenever you want. Your personal notes are never shared.'}}</p></div><div class="actions"><button v-if="!collection.share_uuid" class="button secondary" @click="router.post(`${base}/sharing`)">Enable link sharing</button><template v-else><button class="button" @click="copy">Copy link</button><button class="text-button danger" @click="disable">Turn off</button></template></div><div v-if="collection.share_uuid" class="share-link"><input readonly :value="shareUrl" aria-label="Collection share link" @focus="$event.target.select()"/><small role="status">{{copyStatus}}</small></div></section><div class="section-heading"><h2>{{collection.words.length}} words to discover</h2><button v-if="!shared" class="button secondary" @click="showAdd=true">+ Add from pool</button></div><div class="word-list"><article v-for="word in collection.words" :key="word.id" class="word-row editable"><div><strong>{{word.term}}</strong><p>{{word.definition}}</p><div v-if="!shared && word.note" class="personal-note"><span>YOUR NOTE</span>{{word.note}}</div></div><button v-if="!shared" class="text-button" @click="remove(word)">Remove</button></article><div v-if="!collection.words.length" class="empty"><span>▤</span><h3>This collection is waiting for words.</h3><p v-if="!shared">Add words from your pool to start practicing.</p></div></div><div v-if="!shared" class="form-actions"><button class="text-button danger" @click="destroy">Delete collection</button></div><div v-if="showAdd" class="modal-backdrop" @click.self="showAdd=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="add-title"><div class="section-heading"><h2 id="add-title">Add from your pool</h2><button class="icon-button" aria-label="Close" @click="showAdd=false">×</button></div><form @submit.prevent="add.post(`${base}/words`,{onSuccess:()=>{showAdd=false;add.reset();}})"><Errors :errors="add.errors"/><input type="search" v-model="query" placeholder="Find a word…" aria-label="Find a word"/><div class="pick-list"><label v-for="word in candidates" :key="word.id" class="check"><input type="checkbox" :value="word.id" v-model="add.word_ids"/><span><strong>{{word.term}}</strong><small>{{word.definition}}</small></span></label><p v-if="!candidates.length" class="muted">No more matching words. <Link href="/words">Visit your word pool</Link> to add some.</p></div><div class="form-actions"><button type="button" class="button secondary" @click="showAdd=false">Cancel</button><button class="button" :disabled="!add.word_ids.length || add.processing">Add {{add.word_ids.length}} words</button></div></form></section></div><div v-if="showEdit" class="modal-backdrop" @click.self="showEdit=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="edit-title"><h2 id="edit-title">Edit collection</h2><form @submit.prevent="edit.put(base,{onSuccess:()=>showEdit=false})"><Errors :errors="edit.errors"/><label>Title<input v-model="edit.title" required maxlength="150"/></label><label>Description<textarea v-model="edit.description" maxlength="2000" rows="3"/></label><div class="form-actions"><button type="button" class="button secondary" @click="showEdit=false">Cancel</button><button class="button" :disabled="edit.processing">Save changes</button></div></form></section></div></AppLayout></template>
